// === Tab: mySketch ===
let theShader;

function preload() {
	theShader = createShader(vertShader, fragShader);
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	pixelDensity(1);
}

function draw() {
	background(0);
	shader(theShader);

	theShader.setUniform('iTime', millis() / 1000.0);
	theShader.setUniform('iResolution', [width, height]);

	quad(-1, -1, -1, 1, 1, 1, 1, -1);
}

const vertShader = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;

void main() {
    gl_Position = vec4(aPosition, 1.0);
}
`;

const fragShader = `
precision highp float;

uniform float iTime;
uniform vec2 iResolution;

// Manual tanh (because WebGL 1.0 doesn't have built-in tanh)
vec4 tanh(vec4 x) {
    return (exp(2.0 * x) - 1.0) / (exp(2.0 * x) + 1.0);
}

void main() {
    float t = iTime * 0.2;
    vec2 r = iResolution;
    mat2 R = mat2(cos(t + vec4(0, 33, 11, 0)));

    vec4 O = vec4(0.0);
    float d = 0.0;
    float s;

    for (float i = 1.0; i < 99.0; i += 1.0) {
        vec3 p = vec3( (gl_FragCoord.xy + gl_FragCoord.xy - r.xy) / r.y * d * R, d - 7.0);
        p.yz *= R;

        float turbulence = sin(dot(cos(p + t).yzx, sin(p + t)) / 0.16);
        float cubeSDF = max(abs(p.x), max(abs(p.y), abs(p.z))) - 5.5;
        float distField = max(turbulence, cubeSDF) - i / 80.0;

        s = 0.01 + 0.1 * abs(distField);
        O += max( sin(vec4(3, 2, 1, 1) * i * 0.4) / s , -length(p * p) );
        d += s;
    }

    gl_FragColor = tanh(O * O / 4e5);
}
`;

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

